class BankAccount {
  #balance = 0; // private: unreachable from outside

  deposit(amount) {
    if (amount <= 0) throw new Error('Invalid amount');
    this.#balance += amount;
  }

  get balance() { return this.#balance; } // controlled read access
}

class Animal {
  speak() { return '...'; }
}
class Dog extends Animal {
  speak() { return 'Woof!'; }
}
class Cat extends Animal {
  speak() { return 'Meow!'; }
}

[new Dog(), new Cat()].forEach((a) => console.log(a.speak())); // polymorphism

// Rigid inheritance:
class RobotDuck extends Duck { fly() { /* engine */ } }

// Flexible composition:
class Duck {
  constructor(flyBehavior) { this.flyBehavior = flyBehavior; }
  fly() { return this.flyBehavior.fly(); }
}
const robotDuck = new Duck({ fly: () => 'flies with an engine' });

// Impure, mutates the original array:
function addImpure(arr, x) { arr.push(x); return arr; }

// Pure, changes nothing, returns a new array:
function addPure(arr, x) { return [...arr, x]; }

// Trap: the "pure" copy is only shallow!
function addPureButTrap(list, obj) { const copy = [...list]; copy[0].name = 'modified'; return copy; }
